const revenantSheet=new Image();revenantSheet.assetSrc='assets/revenant-v2.png';
function beginRevenant(e){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'revenantChain',bespoke:true,windup:2.4,origin:{x:e.x,y:e.y},last:{x:e.x,y:e.y},previous:{x:p.x,y:p.y},angle:Math.atan2(e.y-p.y,e.x-p.x),cleared:false,fired:false};}
function revenantContact(from,to){let dx=to.x-from.x,dy=to.y-from.y,l=dx*dx+dy*dy,t=l?Math.max(0,Math.min(1,-(from.x*dx+from.y*dy)/l)):0;return Math.hypot(from.x+dx*t,from.y+dy*t)<=70+1e-8;}
function driftRevenant(e,time){let a=e.attack,t=Math.min(1.6,time),target={x:a.origin.x+Math.cos(a.angle)*70*t,y:a.origin.y+Math.sin(a.angle)*70*t};if(!a.driftBlocked&&!a.cleared){let start={x:e.x,y:e.y},steps=Math.max(1,Math.ceil(dist(e,target)/6));for(let i=1;i<=steps;i++){let q={x:start.x+(target.x-start.x)*i/steps,y:start.y+(target.y-start.y)*i/steps};if(!passable(q.x,q.y,20)||!lineClear(e,q,20)){a.driftBlocked=true;break;}e.x=q.x;e.y=q.y;}}a.last={x:e.x,y:e.y};}
const revenantAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r10e7')return revenantAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='revenantChain'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=320&&clear){beginRevenant(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.8;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,65*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.last)>24){e.attack=null;e.state='idle';e.t=1.5;return;}let before=e.elapsed;e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 let from={x:a.previous.x-e.x,y:a.previous.y-e.y};driftRevenant(e,e.elapsed);
 let span=e.elapsed-before||1,fraction=Math.min(1,Math.max(0,(2.4-before)/span)),target={x:a.previous.x+(p.x-a.previous.x)*fraction,y:a.previous.y+(p.y-a.previous.y)*fraction};
 if(!a.fired&&!a.cleared){if(dist(e,target)>600||!lineClear(e,target)){a.cleared=true;a.clearReason='brokenLink';}else if(dist(a.previous,p)<=220&&lineClear(a.previous,target,13)&&revenantContact(from,{x:target.x-e.x,y:target.y-e.y})){a.cleared=true;a.clearReason='approach';playSound('impact',e.x,e.y);}}a.previous={x:p.x,y:p.y};
 if(!a.fired&&e.elapsed>=2.4){a.fired=true;e.struck=true;if(!a.cleared)hurt(90);playSound('impact',e.x,e.y);}
 if(e.elapsed>=a.windup+1){e.attack=null;e.state='idle';e.t=2.8;}
};
const revenantDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r10e7'||!revenantSheet.complete||!revenantSheet.naturalWidth||!revenantSheet.naturalHeight)return revenantDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0),a=e.attack;if(e.hp<=0)f={row:2,col:3};else if(a?.pattern==='revenantChain')f={row:2,col:a.cleared?3:e.elapsed<.5?0:e.elapsed<a.windup?1:e.elapsed<a.windup+.25?2:3};let q=project(e.x,e.y),sw=revenantSheet.naturalWidth/4,sh=revenantSheet.naturalHeight/3,w=245,h=w*sh/sw,anchor=[[.89,.89,.88,.87],[.83,.82,.8,.78],[.82,.82,.82,.82]][f.row][f.col];ctx.save();ctx.translate(q.x,q.y-12-Math.sin((e.anim||0)*2)*3);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,revenantSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(revenantSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const revenantSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r10e7'?175:revenantSizeBase(e);
const revenantGroundBase=drawGroundEffects;drawGroundEffects=()=>{revenantGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r10e7'):enemies)){let a=e.attack;if(e.species!=='r10e7'||e.hp<=0||a?.pattern!=='revenantChain'||e.elapsed>2.7||!visibleAt(e.x,e.y))continue;groundRing(e.x,e.y,70,'#98efd3',3);if(a.cleared)continue;let from=project(e.x,e.y),to=project(p.x,p.y);ctx.save();ctx.strokeStyle=a.fired?'#f5d6ff':'#c1a5de';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(from.x,from.y-30);ctx.lineTo(to.x,to.y-30);ctx.stroke();for(let i=1;i<7;i++){let t=i/7;ctx.beginPath();ctx.ellipse(from.x+(to.x-from.x)*t,from.y+(to.y-from.y)*t-30,4,7,-.4,0,Math.PI*2);ctx.stroke();}ctx.restore();groundRing(p.x,p.y,32*Math.max(0,1-e.elapsed/2.4),'#c7a3e5',2);}};
if(typeof registerDirectEnemy==='function')registerDirectEnemy('r10e7',animateEnemy,drawRegionEnemy);
